import os
import numpy as np

# Load experiment data
experiment_data = np.load(
    os.path.join(os.getcwd(), "working", "experiment_data.npy"), allow_pickle=True
).item()

# Extract metrics
for dataset_name, dataset_info in experiment_data.items():
    print(f"\nDataset: {dataset_name}")
    for data_type, metrics in dataset_info.items():
        for metric_name, values in metrics.items():
            if isinstance(values, list) and values:
                best_value = (
                    max(values) if "loss" not in metric_name.lower() else min(values)
                )
                print(
                    f"{data_type} {metric_name.replace('train', 'accuracy') if 'train' in data_type else metric_name}: {best_value:.4f}"
                )
